BEGIN;
SELECT plan(17);
INSERT INTO public.staff(id,first_name,last_name,email,role,status) VALUES('fa250800-0000-4000-8000-000000000001','Matthew','Fixture','mail-staff@example.test','ADMINSTAFF','ACTIVE');
INSERT INTO public.contacts(id,email,contact_type,staff_id) VALUES('fa250800-0000-4000-8000-000000000002','mail-alias@example.test','STAFF','fa250800-0000-4000-8000-000000000001');
INSERT INTO public.email_folders(id,name,role) VALUES('view-inbox','Inbox','inbox'),('view-drafts','Drafts','drafts'),('view-deleted','Deleted Items','deleteditems');
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT is((SELECT count(*) FROM public.email_people_for_address(' MAIL-STAFF@example.test ')),1::bigint,'a staff profile and synchronized Contact resolve once');
SELECT is((SELECT record_id::text FROM public.email_people_for_address('mail-alias@example.test')),'fa250800-0000-4000-8000-000000000001','secondary linked staff email resolves the same staff');
SELECT public.email_apply_sync_page('view-inbox',NULL,NULL,false,'[{"id":"view-original","threadId":"view-thread","folderId":"view-inbox","sender":"mail-staff@example.test","receivedAt":"2026-11-01T00:00:00Z","draft":false}]','{}',true,coalesce((SELECT address FROM public.email_mailbox_identity WHERE singleton),'admin@altitutor.com'));
SELECT is(public.email_thread_detail('view-thread')->'links'->0->>'recordId','fa250800-0000-4000-8000-000000000001','known staff participant is linked on observation');
SELECT public.email_apply_sync_page('view-drafts',NULL,NULL,false,'[{"id":"view-live","threadId":"view-thread","folderId":"view-drafts","sender":"admin@altitutor.com","draft":true},{"id":"view-deleted-draft","threadId":"view-thread","folderId":"view-deleted","sender":"admin@altitutor.com","draft":true},{"id":"view-removed-draft","threadId":"view-thread","folderId":"view-drafts","sender":"admin@altitutor.com","draft":true}]','{}',true,coalesce((SELECT address FROM public.email_mailbox_identity WHERE singleton),'admin@altitutor.com'));
UPDATE public.email_messages SET removed=true WHERE id='view-removed-draft';
SELECT is(jsonb_array_length(public.email_thread_detail('view-thread')->'messages'),2,'thread excludes removed and Deleted Items drafts');
SELECT ok(EXISTS(SELECT 1 FROM jsonb_array_elements(public.email_thread_detail('view-thread')->'messages') m WHERE m->>'id'='view-live'),'live draft remains in the editable thread');
SELECT public.email_apply_sync_page('view-deleted',NULL,NULL,false,'[{"id":"view-live","threadId":"view-thread","folderId":"view-deleted","draft":true}]','{}',true,coalesce((SELECT address FROM public.email_mailbox_identity WHERE singleton),'admin@altitutor.com'));
SELECT is(jsonb_array_length(public.email_thread_detail('view-thread')->'messages'),1,'a discarded draft disappears even though Microsoft retains isDraft');
INSERT INTO public.email_threads(id) SELECT 'view-page-'||g FROM generate_series(1,60) g;
INSERT INTO public.email_messages(id,thread_id,folder_id,data,occurred_at) SELECT 'view-page-msg-'||g,'view-page-'||g,'view-inbox',jsonb_build_object('sender','page-from@example.test','subject','Page '||g,'draft',false),now() FROM generate_series(1,60) g;
SELECT is(jsonb_array_length(public.email_list_threads('view-inbox','','all',0,50,'received','desc','PAGE-FROM@example.test')->'threads'),50,'From is case insensitive and filters before pagination');
SELECT is(public.email_list_threads('view-inbox','','all',0,50,'received','desc','page-from@example.test')->>'hasMore','true','From filtering retains correct pagination');
SELECT is(jsonb_array_length(public.email_list_threads('view-inbox','','all',0,100,'received','desc','mail-staff@example.test,page-from@example.test')->'threads'),61,'From supports multiple senders');
SELECT is(jsonb_array_length(public.email_list_threads('view-inbox','','all',0,50,'received','desc','unknown@example.test')->'threads'),0,'unmatched From returns no rows');
SELECT ok(NOT has_function_privilege('anon','public.email_sender_options()','EXECUTE'),'sender options are unavailable anonymously');
INSERT INTO public.email_messages(id,thread_id,folder_id,data) VALUES('view-header-cas','view-thread','view-drafts','{"draft":true,"changeKey":"v1","bodyText":"Keep this body","extra":"retained"}');
SELECT ok(public.email_cache_draft_reply_targets('view-header-cas','v1',ARRAY['<original@example.test>']),'matching draft version accepts reply metadata');
SELECT is((SELECT data->>'bodyText' FROM public.email_messages WHERE id='view-header-cas'),'Keep this body','header enrichment preserves body data');
UPDATE public.email_messages SET data=data || '{"changeKey":"v3","bodyText":"Newer Outlook work"}' WHERE id='view-header-cas';
SELECT ok(NOT public.email_cache_draft_reply_targets('view-header-cas','v1',ARRAY['<stale@example.test>']),'stale header response cannot patch newer delta data');
SELECT is((SELECT data->>'bodyText' FROM public.email_messages WHERE id='view-header-cas'),'Newer Outlook work','newer body remains intact after the stale response');
SELECT ok(NOT has_function_privilege('authenticated','public.email_cache_draft_reply_targets(text,text,text[])','EXECUTE'),'reply enrichment is a service-only projection operation');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM public.email_sender_options()),0::bigint,'non-admin sender options retain mailbox RLS');
SELECT * FROM finish();
ROLLBACK;
